/* 학습 해설
 * OPP·성능 지점과 전압 순서
 * Clock 주파수를 바꿀 때 전압·전력 domain·대역폭 요구를 올바른 순서로 적용해야 합니다.
 * Operating Performance Point는 rate·supply·level·required OPP·bandwidth 등 허용 성능 조합을 표현합니다. Scaling up은 필요한 자원을 먼저 준비하고 rate를 높이며 down은 rate·자원을 안전한 순서로 낮춥니다. 단일 clock 외 여러 의존 관계와 provider callback·실패 처리가 있습니다.
 * 지원 cpufreq/devfreq·OPP consumer의 table·available 상태·참조 API와 transition을 관찰합니다. Chip의 검증된 OPP 조합과 regulator·clock 지원을 따르고 임의 주파수와 전압을 독립적으로 선택하지 않습니다.
 */
static int _set_opp(struct device *dev, struct opp_table *opp_table,
		    struct dev_pm_opp *opp, void *clk_data, bool forced)
{
	struct dev_pm_opp *old_opp;
	int scaling_down, ret;

	if (unlikely(!opp))
		return _disable_opp_table(dev, opp_table);

	/* Find the currently set OPP if we don't know already */
	if (unlikely(!opp_table->current_opp))
		_find_current_opp(dev, opp_table);

	old_opp = opp_table->current_opp;

	/* Return early if nothing to do */
	if (!forced && old_opp == opp && opp_table->enabled) {
		dev_dbg_ratelimited(dev, "%s: OPPs are same, nothing to do\n", __func__);
		return 0;
	}

	dev_dbg(dev, "%s: switching OPP: Freq %lu -> %lu Hz, Level %u -> %u, Bw %u -> %u\n",
		__func__, old_opp->rates[0], opp->rates[0], old_opp->level,
		opp->level, old_opp->bandwidth ? old_opp->bandwidth[0].peak : 0,
		opp->bandwidth ? opp->bandwidth[0].peak : 0);

