/* 학습 해설
 * Generic Radix Tree·희소 고정 크기 객체
 * 큰 index 공간에 고정 크기 객체를 드문드문 저장할 때 전체 배열을 처음부터 할당하지 않을 수 있습니다.
 * Genradix는 page 단위 leaf와 내부 pointer node로 byte offset을 분해해 저장 공간을 찾습니다. 필요한 가지를 할당하고 offset이 기존 depth 밖이면 root 깊이를 늘립니다. 새 slot은 zero 초기화되지만 없는 slot 조회와 할당 조회는 다른 API입니다.
 * 타입을 선언한 genradix API로 index를 변환하고 ptr과 ptr_alloc을 구분합니다. GFP·할당 실패·동시 접근·free 수명을 관리하며 slot pointer를 tree 해제 이후 사용하지 않습니다.
 */
void *__genradix_ptr_alloc(struct __genradix *radix, size_t offset,
			   struct genradix_node **preallocated,
			   gfp_t gfp_mask)
{
	struct genradix_root *v = READ_ONCE(radix->root);
	struct genradix_node *n, *new_node = NULL;
	unsigned level;

	if (preallocated)
		swap(new_node, *preallocated);

	/* Increase tree depth if necessary: */
	while (1) {
		struct genradix_root *r = v, *new_root;

		n	= genradix_root_to_node(r);
		level	= genradix_root_to_depth(r);

		if (n && ilog2(offset) < genradix_depth_shift(level))
			break;

		if (!new_node) {
			new_node = genradix_alloc_node(gfp_mask);
			if (!new_node)
				return NULL;
		}

