/* 학습 해설
 * Timerqueue·가장 가까운 만료의 Tree
 * 가장 가까운 만료를 자주 조회하면서 임의 타이머를 삽입·삭제할 때 순서 tree와 최소값 cache가 유용합니다.
 * Timerqueue는 expires 기준 red-black tree와 cached leftmost node를 사용합니다. Add는 새 node가 가장 이른 만료인지 반환하고 delete는 제거 후 queue가 비어 있지 않은지를 반환합니다. 함수별 bool 의미가 다르며 라이브러리 자체는 locking을 하지 않습니다.
 * head·node를 초기화하고 외부 lock 등으로 모든 조작을 직렬화합니다. 이미 들어간 node를 다시 add하지 않으며 만료 변경은 올바른 제거·재삽입 규칙으로 정렬 불변식을 유지합니다.
 */
bool timerqueue_add(struct timerqueue_head *head, struct timerqueue_node *node)
{
	/* Make sure we don't add nodes that are already added */
	WARN_ON_ONCE(!RB_EMPTY_NODE(&node->node));

	return rb_add_cached(&node->node, &head->rb_root, __timerqueue_less);
}
EXPORT_SYMBOL_GPL(timerqueue_add);

/**
 * timerqueue_del - Removes a timer from the timerqueue.
 *
 * @head: head of timerqueue
 * @node: timer node to be removed
 *
 * Removes the timer node from the timerqueue. Returns true if the queue is
 * not empty after the remove.
 */
bool timerqueue_del(struct timerqueue_head *head, struct timerqueue_node *node)
{
	WARN_ON_ONCE(RB_EMPTY_NODE(&node->node));

	rb_erase_cached(&node->node, &head->rb_root);
	RB_CLEAR_NODE(&node->node);

	return !RB_EMPTY_ROOT(&head->rb_root.rb_root);

