/* 학습 해설
 * Lockref·잠금과 참조의 결합
 * 참조 갱신과 객체 잠금 상태를 한 atomic 단위에서 다루면 경합이 없는 획득의 lock 비용을 줄일 수 있습니다.
 * Lockref는 lock과 count가 들어 있는 표현에서 지원되는 cmpxchg 빠른 경로를 사용하고 실패·지원 조건에 따라 spinlock 경로로 갑니다. Get_not_zero는 count가 양수일 때만 증가시키며 0 또는 dead 계열의 상태를 되살리지 않습니다.
 * Lockref 초기화와 get/put 변형별 반환·dead 상태 규약을 따릅니다. 이미 free된 주소에서 get을 시도하지 않도록 lookup 수명을 별도로 보호하고 모든 helper를 일반 refcount_t와 동일하게 취급하지 않습니다.
 */
int lockref_get_not_zero(struct lockref *lockref)
{
	int retval;

	CMPXCHG_LOOP(
		new.count++;
		if (old.count <= 0)
			return 0;
	,
		return 1;
	);

	spin_lock(&lockref->lock);
	retval = 0;
	if (lockref->count > 0) {
		lockref->count++;
		retval = 1;
	}
	spin_unlock(&lockref->lock);
	return retval;
}
EXPORT_SYMBOL(lockref_get_not_zero);

/**
 * lockref_put_not_zero - Decrements count unless count <= 1 before decrement
 * @lockref: pointer to lockref structure
 * Return: 1 if count updated successfully or 0 if count would become zero
 */

