/* 학습 해설
 * Klist·참조가 있는 목록 순회
 * 순회하는 동안 다른 흐름이 node 제거를 요청해도 현재 객체를 안전하게 유지할 수 있어야 합니다.
 * Klist는 list node와 kref·dead 상태·get/put callback을 결합합니다. Iterator는 현재 node 참조를 유지하고 next에서 기존 참조를 내려놓고 살아 있는 다음 node의 참조를 얻습니다. 목록 보호 lock과 객체 callback 수명은 연결되지만 별도 역할입니다.
 * Klist와 node를 초기화하고 iterator init·next·exit를 균형 있게 호출합니다. Get/put callback과 del/remove의 대기 규약을 확인하며 iterator가 끝나기 전에 잡은 객체를 무조건 free하지 않습니다.
 */
struct klist_node *klist_next(struct klist_iter *i)
{
	void (*put)(struct klist_node *) = i->i_klist->put;
	struct klist_node *last = i->i_cur;
	struct klist_node *next;
	unsigned long flags;

	spin_lock_irqsave(&i->i_klist->k_lock, flags);

	if (last) {
		next = to_klist_node(last->n_node.next);
		if (!klist_dec_and_del(last))
			put = NULL;
	} else
		next = to_klist_node(i->i_klist->k_list.next);

	i->i_cur = NULL;
	while (next != to_klist_node(&i->i_klist->k_list)) {
		if (likely(!knode_dead(next))) {
			kref_get(&next->n_ref);
			i->i_cur = next;
			break;
		}
		next = to_klist_node(next->n_node.next);
	}

