/* 학습 해설
 * Objpool·CPU별 객체 Ring
 * 할당하기 어려운 interrupt·probe 경로에서 준비된 객체를 CPU별 ring에서 가져오면 일반 allocation 비용을 줄일 수 있습니다.
 * Objpool은 고정 capacity의 per-CPU ring array를 사용하며 head·tail·last sequence와 mask로 slot 예약·공개·소비를 분리합니다. CAS와 acquire/release가 경합을 처리하고 pop은 local부터 다른 possible CPU slot을 탐색할 수 있습니다.
 * objpool_init으로 객체를 준비하고 pop 실패 NULL을 처리합니다. 사용 후 push하거나 종료 중 outstanding object를 drop하는 계약을 따릅니다. 같은 객체 중복 push·잘못된 객체 반환·fini와 진행 중 push 경합을 금지합니다.
 */
static inline void *objpool_pop(struct objpool_head *pool)
{
	void *obj = NULL;
	unsigned long flags;
	int i, cpu;

	/* disable local irq to avoid preemption & interruption */
	raw_local_irq_save(flags);

	cpu = raw_smp_processor_id();
	for (i = 0; i < pool->nr_possible_cpus; i++) {
		obj = __objpool_try_get_slot(pool, cpu);
		if (obj)
			break;
		cpu = cpumask_next_wrap(cpu, cpu_possible_mask, -1, 1);
	}
	raw_local_irq_restore(flags);

	return obj;
}

/* adding object to slot, abort if the slot was already full */
static inline int
__objpool_try_add_slot(void *obj, struct objpool_head *pool, int cpu)
{
	struct objpool_slot *slot = pool->cpu_slots[cpu];

