/* 학습 해설
 * Parman·우선순위 정렬 배열 관리
 * Hardware table처럼 index 순서가 우선순위를 나타낼 때 항목 추가로 주변 구간을 이동해야 합니다.
 * Parman은 priority별 item 그룹과 array index를 관리하고 알고리즘의 add/remove 및 caller move·resize callback으로 저장 배치를 맞춥니다. Priority 순서와 같은 priority의 item 범위를 보존하며 logical item과 물리 index 수명은 다릅니다.
 * Priority와 item을 초기화하고 ops의 move·resize가 실제 table 배치를 갱신하도록 구현합니다. 모든 locking은 caller가 제공하며 callback 실패·capacity·동시 lookup과 이동 조건을 확인합니다.
 */
int parman_item_add(struct parman *parman, struct parman_prio *prio,
		    struct parman_item *item)
{
	return parman->algo->item_add(parman, prio, item);
}
EXPORT_SYMBOL(parman_item_add);

/**
 * parman_item_remove - deletes parman item
 * @parman:	parman instance
 * @prio:	parman prio instance to delete the item from
 * @item:	parman item instance
 *
 * Note: all locking must be provided by the caller.
 */
void parman_item_remove(struct parman *parman, struct parman_prio *prio,
			struct parman_item *item)
{
	parman->algo->item_remove(parman, prio, item);
}
EXPORT_SYMBOL(parman_item_remove);

