/* 학습 해설
 * Linear Range·수치와 Selector 변환
 * Regulator 등의 register selector를 실제 전압·수치 범위와 연결할 때 구간별 선형식을 관리할 수 있습니다.
 * Linear range는 최소 값·selector 최소/최대·step을 담습니다. 값=min+(selector-min_sel)*step이며 low selector는 원하는 값 이하의 범위 위치를 정수 나눗셈으로 찾습니다. Step 0은 고정 값 구간이고 반환 코드와 found flag가 서로 다른 정보를 줍니다.
 * 지원 hardware 범위의 단위를 맞추고 low/high/within API 차이를 선택합니다. Range 밖·step 0·overflow·found flag를 처리하며 반올림 방향이 제한 조건에 맞는지 확인합니다.
 */
int linear_range_get_selector_low(const struct linear_range *r,
				  unsigned int val, unsigned int *selector,
				  bool *found)
{
	*found = false;

	if (r->min > val)
		return -EINVAL;

	if (linear_range_get_max_value(r) < val) {
		*selector = r->max_sel;
		return 0;
	}

	*found = true;

	if (r->step == 0)
		*selector = r->min_sel;
	else
		*selector = (val - r->min) / r->step + r->min_sel;

	return 0;
}
EXPORT_SYMBOL_GPL(linear_range_get_selector_low);

/**
 * linear_range_get_selector_low_array - return linear range selector for value
 * @r:		pointer to array of linear ranges where selector is looked from
 * @ranges:	amount of ranges to scan from array
