/* 학습 해설
 * BCH·유한체 오류 정정
 * Flash 등의 제한된 bit 오류를 정정하려면 data뿐 아니라 code의 parity와 유한체 계산이 필요합니다.
 * Binary BCH code는 GF(2^m)의 다항식 구조로 parity를 만들고 syndrome·오류 locator 등을 통해 정정 위치를 구합니다. Linux encoder는 generator 관련 table로 word·byte 처리를 가속합니다. M·t·data 길이·bit ordering에 따른 code 규약과 최대 정정 능력을 맞춰야 합니다.
 * BCH control을 초기화하고 ecc 길이·raw data·stored parity 규약을 맞춥니다. Decode가 주는 bit 위치와 실패를 검사하고 caller가 data를 수정합니다. CRC처럼 탐지만 하는 코드와 구분하며 t를 넘은 오류의 정정을 보장하지 않습니다.
 */
void bch_encode(struct bch_control *bch, const uint8_t *data,
		unsigned int len, uint8_t *ecc)
{
	const unsigned int l = BCH_ECC_WORDS(bch)-1;
	unsigned int i, mlen;
	unsigned long m;
	uint32_t w, r[BCH_ECC_MAX_WORDS];
	const size_t r_bytes = BCH_ECC_WORDS(bch) * sizeof(*r);
	const uint32_t * const tab0 = bch->mod8_tab;
	const uint32_t * const tab1 = tab0 + 256*(l+1);
	const uint32_t * const tab2 = tab1 + 256*(l+1);
	const uint32_t * const tab3 = tab2 + 256*(l+1);
	const uint32_t *pdata, *p0, *p1, *p2, *p3;

	if (WARN_ON(r_bytes > sizeof(r)))
		return;

	if (ecc) {
		/* load ecc parity bytes into internal 32-bit buffer */
		load_ecc8(bch, bch->ecc_buf, ecc);
	} else {
		memset(bch->ecc_buf, 0, r_bytes);
	}

	/* process first unaligned data bytes */
	m = ((unsigned long)data) & 3;

