/* 학습 해설
 * LZ4·Literal와 Match Token
 * 반복 문자열을 이전 출력 위치의 참조로 표현하면 빠르게 압축·해제할 수 있지만 입력·출력 경계를 검증해야 합니다.
 * LZ4 block의 token은 literal와 match 길이 정보를 담고 확장 byte·offset으로 이전 출력의 반복을 표현합니다. Match 복사는 겹칠 수 있어 일반 memcpy와 계약이 다릅니다. Safe decoder는 compressedSize·output capacity와 입력 끝을 기준으로 검증합니다.
 * Block과 frame format·dictionary를 구분하고 압축 길이·최대 출력 공간을 검증한 safe API를 사용합니다. 음수 오류와 복원 길이를 확인하고 압축 data가 신뢰된 원본이라는 이유로 bounds 검사를 생략하지 않습니다.
 */
int LZ4_decompress_safe(const char *source, char *dest,
	int compressedSize, int maxDecompressedSize)
{
	return LZ4_decompress_generic(source, dest,
				      compressedSize, maxDecompressedSize,
				      endOnInputSize, decode_full_block,
				      noDict, (BYTE *)dest, NULL, 0);
}

int LZ4_decompress_safe_partial(const char *src, char *dst,
	int compressedSize, int targetOutputSize, int dstCapacity)
{
	dstCapacity = min(targetOutputSize, dstCapacity);
	return LZ4_decompress_generic(src, dst, compressedSize, dstCapacity,
				      endOnInputSize, partial_decode,
				      noDict, (BYTE *)dst, NULL, 0);
}

int LZ4_decompress_fast(const char *source, char *dest, int originalSize)
{
	return LZ4_decompress_generic(source, dest, 0, originalSize,
				      endOnOutputSize, decode_full_block,
				      withPrefix64k,
				      (BYTE *)dest - 64 * KB, NULL, 0);
}

