 * LZO·짧은 Match와 스트림
 * 빠른 해제를 중시하는 압축에서 literal run과 여러 길이·거리 match 표현의 비용을 조정할 수 있습니다.
 * LZO1X는 literal와 이전 data의 match를 compact byte 규칙으로 인코딩합니다. Compressor는 working dictionary로 후보를 찾고 decoder는 길이·offset과 종료 표식을 해석합니다. LZO-RLE 변형은 zero run 등의 별도 지원을 가지며 format과 version을 맞춰야 합니다.
 * Kernel LZO API의 worst-case 출력 크기·workmem 크기를 준비하고 반환과 실제 out_len을 검사합니다. 해제는 input/output 범위를 검사하는 safe API를 사용하며 LZO와 LZO-RLE를 이름만 같다고 섞지 않습니다.
 */
int lzo1x_1_compress(const unsigned char *in, size_t in_len,
		     unsigned char *out, size_t *out_len,
		     void *wrkmem)
{
	return lzogeneric1x_1_compress(in, in_len, out, out_len, wrkmem, 0);
}

int lzorle1x_1_compress(const unsigned char *in, size_t in_len,
		     unsigned char *out, size_t *out_len,
		     void *wrkmem)
{
	return lzogeneric1x_1_compress(in, in_len, out, out_len,
				       wrkmem, LZO_VERSION);
}

EXPORT_SYMBOL_GPL(lzo1x_1_compress);
EXPORT_SYMBOL_GPL(lzorle1x_1_compress);

MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("LZO1X-1 Compressor");

