/* 학습 해설
 * Zstd·반복과 Entropy 부호화
 * 압축 성능·해제 속도·dictionary 재사용을 조절하려면 literal와 sequence coding을 구분해야 합니다.
 * Zstd는 frame과 block에서 literal·match sequence를 표현하고 Huffman·FSE 등의 entropy coding을 사용합니다. Window·dictionary·repeated offset·checksum 조건을 해석하며 raw/RLE/compressed block이 존재합니다. Context는 재사용할 상태와 dictionary 연결을 관리합니다.
 * Kernel zstd wrapper의 workspace·context·지원 API를 우선 사용하고 입력 길이·destination capacity·window limit을 검증합니다. size_t 반환의 ZSTD_isError 규약을 확인하고 모든 양수 반환을 성공 출력 길이로 판단하지 않습니다.
 */
size_t ZSTD_decompressDCtx(ZSTD_DCtx* dctx, void* dst, size_t dstCapacity, const void* src, size_t srcSize)
{
    return ZSTD_decompress_usingDDict(dctx, dst, dstCapacity, src, srcSize, ZSTD_getDDict(dctx));
}


size_t ZSTD_decompress(void* dst, size_t dstCapacity, const void* src, size_t srcSize)
{
#if defined(ZSTD_HEAPMODE) && (ZSTD_HEAPMODE>=1)
    size_t regenSize;
    ZSTD_DCtx* const dctx =  ZSTD_createDCtx_internal(ZSTD_defaultCMem);
    RETURN_ERROR_IF(dctx==NULL, memory_allocation, "NULL pointer!");
    regenSize = ZSTD_decompressDCtx(dctx, dst, dstCapacity, src, srcSize);
    ZSTD_freeDCtx(dctx);
    return regenSize;
#else   /* stack mode */
    ZSTD_DCtx dctx;
    ZSTD_initDCtx_internal(&dctx);
    return ZSTD_decompressDCtx(&dctx, dst, dstCapacity, src, srcSize);
#endif
}


