/* 학습 해설
 * Window Minmax·제한된 시간의 극값
 * 최근 RTT·대역폭의 극값을 전체 이력 없이 일정한 저장 공간으로 추적할 수 있습니다.
 * Nichols의 windowed min/max tracker는 값·시간을 가진 후보 세 개를 유지하고 새 극값이나 만료에 따라 reset·shift·subwindow 후보를 갱신합니다. Update 시간·공간은 상수지만 모든 입력에서 정확한 전체 window 극값과 같다고 보장하는 저장 구조는 아닙니다.
 * minmax를 초기화하고 같은 시간 단위의 monotonic sample·window와 max/min helper를 사용합니다. Timestamp wrap 조건과 비교 규약을 확인하며 정확한 전체 window가 필요한 요구에 무조건 대체하지 않습니다.
 */
u32 minmax_running_max(struct minmax *m, u32 win, u32 t, u32 meas)
{
	struct minmax_sample val = { .t = t, .v = meas };

	if (unlikely(val.v >= m->s[0].v) ||	  /* found new max? */
	    unlikely(val.t - m->s[2].t > win))	  /* nothing left in window? */
		return minmax_reset(m, t, meas);  /* forget earlier samples */

	if (unlikely(val.v >= m->s[1].v))
		m->s[2] = m->s[1] = val;
	else if (unlikely(val.v >= m->s[2].v))
		m->s[2] = val;

	return minmax_subwin_update(m, win, &val);
}
EXPORT_SYMBOL(minmax_running_max);

/* Check if new measurement updates the 1st, 2nd or 3rd choice min. */
u32 minmax_running_min(struct minmax *m, u32 win, u32 t, u32 meas)
{
	struct minmax_sample val = { .t = t, .v = meas };

	if (unlikely(val.v <= m->s[0].v) ||	  /* found new min? */
	    unlikely(val.t - m->s[2].t > win))	  /* nothing left in window? */
		return minmax_reset(m, t, meas);  /* forget earlier samples */

