/* 학습 해설
 * PerCPU Counter·근사와 정확한 합
 * 자주 갱신되는 전체 count를 매번 global lock으로 수정하면 CPU 사이 cache 경합이 커집니다.
 * PerCPU counter는 각 CPU의 작은 변화와 global count를 나눠 저장합니다. Batch 기준을 넘으면 local 잔량과 새 변화량을 global에 합치고 local을 조정합니다. 빠른 read는 잔량을 포함하지 않는 근사이고 sum은 CPU 잔량을 순회하는 더 정확하고 비싼 경로입니다.
 * 초기화·add·read·sum·destroy API와 caller context를 따릅니다. Exact 동시 snapshot 요구는 별도로 검토하고 hotplug의 dying CPU fold·batch 오차·정수 범위를 확인합니다. Check와 add를 나눠서 엄격 한도를 보장하려 하지 않습니다.
 */
void percpu_counter_add_batch(struct percpu_counter *fbc, s64 amount, s32 batch)
{
	s64 count;
	unsigned long flags;

	count = this_cpu_read(*fbc->counters);
	do {
		if (unlikely(abs(count + amount) >= batch)) {
			raw_spin_lock_irqsave(&fbc->lock, flags);
			/*
			 * Note: by now we might have migrated to another CPU
			 * or the value might have changed.
			 */
			count = __this_cpu_read(*fbc->counters);
			fbc->count += count + amount;
			__this_cpu_sub(*fbc->counters, count);
			raw_spin_unlock_irqrestore(&fbc->lock, flags);
			return;
		}
	} while (!this_cpu_try_cmpxchg(*fbc->counters, &count, count + amount));
}
#else
/*
 * local_irq_save() is used to make the function irq safe:
 * - The slow path would be ok as protected by an irq-safe spinlock.
 * - this_cpu_add would be ok as it is irq-safe by definition.
 */

