/* 학습 해설
 * Flex Proportions·기간별 비율
 * 최근 event 비율을 오래된 이력보다 더 반영하려면 전체·local count를 기간에 따라 감쇠시킬 수 있습니다.
 * Flex proportions는 global/local event와 period를 관리하고 기간이 바뀌면 오래된 기여를 shift 기반으로 줄입니다. Local 상태는 global period와 차이를 맞추며 seqcount·percpu counter로 관찰과 업데이트를 연결합니다. 영구 누적 총합과 시간 감쇠된 비율은 다른 통계입니다.
 * Global/local 구조를 초기화하고 event 증가·new_period·fraction API의 locking·기간 조건을 따릅니다. 샘플 적음·분모·integer rounding과 동시 event를 고려하며 기간 갱신 주체를 직렬화합니다.
 */
bool fprop_new_period(struct fprop_global *p, int periods)
{
	s64 events = percpu_counter_sum(&p->events);

	/*
	 * Don't do anything if there are no events.
	 */
	if (events <= 1)
		return false;
	preempt_disable_nested();
	write_seqcount_begin(&p->sequence);
	if (periods < 64)
		events -= events >> periods;
	/* Use addition to avoid losing events happening between sum and set */
	percpu_counter_add(&p->events, -events);
	p->period += periods;
	write_seqcount_end(&p->sequence);
	preempt_enable_nested();

	return true;
}

/*
 * ---- PERCPU ----
 */
#define PROP_BATCH (8*(1+ilog2(nr_cpu_ids)))

