/* 학습 해설
 * CAST5·변환·상태와 적용 조건
 * 같은 Feistel 계열이라도 key 길이에 따른 round 수와 세 가지 round 함수의 차이가 있습니다.
 * CAST5는 64bit block의 좌우 u32를 F1·F2·F3로 교대 갱신합니다. Masking key Km와 rotation key Kr를 따로 사용하고 c->rr에 따라 12round 뒤 마지막 4round를 생략하거나 수행합니다. Add·subtract·XOR와 rotation의 순서가 함수별로 다릅니다.
 * 지원 key 길이·reduced-round 조건·mode를 원본 setkey와 test vector로 대조합니다. 과거 호환 구현을 새 protocol 추천으로 해석하지 않고 block·IV·authentication 한계를 확인합니다.
 */
void __cast5_encrypt(struct cast5_ctx *c, u8 *outbuf, const u8 *inbuf)
{
	u32 l, r, t;
	u32 I;			/* used by the Fx macros */
	u32 *Km;
	u8 *Kr;

	Km = c->Km;
	Kr = c->Kr;

	/* (L0,R0) <-- (m1...m64).  (Split the plaintext into left and
	 * right 32-bit halves L0 = m1...m32 and R0 = m33...m64.)
	 */
	l = get_unaligned_be32(inbuf);
	r = get_unaligned_be32(inbuf + 4);

	/* (16 rounds) for i from 1 to 16, compute Li and Ri as follows:
	 *  Li = Ri-1;
	 *  Ri = Li-1 ^ f(Ri-1,Kmi,Kri), where f is defined in Section 2.2
	 * Rounds 1, 4, 7, 10, 13, and 16 use f function Type 1.
	 * Rounds 2, 5, 8, 11, and 14 use f function Type 2.
	 * Rounds 3, 6, 9, 12, and 15 use f function Type 3.
	 */

	t = l; l = r; r = t ^ F1(r, Km[0], Kr[0]);
	t = l; l = r; r = t ^ F2(r, Km[1], Kr[1]);

