/* 학습 해설
 * TEA·XTEA·변환·상태와 적용 조건
 * 짧은 코드의 cipher를 통해 unsigned 연산·shift·XOR와 key 선택이 결과에 어떻게 반영되는지 볼 수 있습니다.
 * TEA는 두 u32 state와 네 u32 key에 sum·delta를 더하면서 좌우를 교대 갱신합니다. 32cycle에서 각 cycle의 두 갱신이 실행됩니다. XTEA는 sum에 따른 key 선택과 round 식이 다르고 XETA도 별도 구현입니다. 과거 약점과 64bit block 한계 때문에 짧다는 이유로 새 보안 설계를 만들지 않습니다.
 * 원본의 little-endian·u32 modulo·연산자 우선순위·delta·cycle을 vector와 대조합니다. TEA·XTEA·XETA 이름과 wire format을 정확히 지정하고 별도 mode·IV·인증을 요구합니다.
 */
static void tea_encrypt(struct crypto_tfm *tfm, u8 *dst, const u8 *src)
{
	u32 y, z, n, sum = 0;
	u32 k0, k1, k2, k3;
	struct tea_ctx *ctx = crypto_tfm_ctx(tfm);
	const __le32 *in = (const __le32 *)src;
	__le32 *out = (__le32 *)dst;

	y = le32_to_cpu(in[0]);
	z = le32_to_cpu(in[1]);

	k0 = ctx->KEY[0];
	k1 = ctx->KEY[1];
	k2 = ctx->KEY[2];
	k3 = ctx->KEY[3];

	n = TEA_ROUNDS;

	while (n-- > 0) {
		sum += TEA_DELTA;
		y += ((z << 4) + k0) ^ (z + sum) ^ ((z >> 5) + k1);
		z += ((y << 4) + k2) ^ (y + sum) ^ ((y >> 5) + k3);
	}

	out[0] = cpu_to_le32(y);
	out[1] = cpu_to_le32(z);

