/* 학습 해설
 * RIPEMD160·변환·상태와 적용 조건
 * 같은 입력 block을 두 lane에서 다른 순서로 처리하고 마지막에 결합하는 hash 설계를 볼 수 있습니다.
 * RIPEMD160은 512bit block과 다섯 u32 hash word를 사용합니다. Left/right lane이 각각 80step의 Boolean 함수·상수·message word 순서·rotation을 다르게 적용하고 lane 결과를 이전 state와 결합합니다. Digest 160bit와 입력 block 512bit는 서로 다른 크기입니다.
 * Shash init/update/final과 endian·padding·length·vector를 대조합니다. Digest를 password KDF나 keyed MAC으로 자동 대체하지 않고 보안 규약에 요구된 algorithm과 output 폭을 맞춥니다.
 */
static void rmd160_transform(u32 *state, const __le32 *in)
{
	u32 aa, bb, cc, dd, ee, aaa, bbb, ccc, ddd, eee;

	/* Initialize left lane */
	aa = state[0];
	bb = state[1];
	cc = state[2];
	dd = state[3];
	ee = state[4];

	/* Initialize right lane */
	aaa = state[0];
	bbb = state[1];
	ccc = state[2];
	ddd = state[3];
	eee = state[4];

	/* round 1: left lane */
	ROUND(aa, bb, cc, dd, ee, F1, K1, in[0],  11);
	ROUND(ee, aa, bb, cc, dd, F1, K1, in[1],  14);
	ROUND(dd, ee, aa, bb, cc, F1, K1, in[2],  15);
	ROUND(cc, dd, ee, aa, bb, F1, K1, in[3],  12);
	ROUND(bb, cc, dd, ee, aa, F1, K1, in[4],   5);
	ROUND(aa, bb, cc, dd, ee, F1, K1, in[5],   8);
	ROUND(ee, aa, bb, cc, dd, F1, K1, in[6],   7);

