/* 학습 해설
 * Whirlpool·변환·상태와 적용 조건
 * Block cipher 형태의 변환을 hash 압축 함수에 이용할 때 round key와 이전 hash의 관계를 이해할 수 있습니다.
 * Whirlpool은 512bit block·hash state를 사용하고 이전 hash를 round key 출발점으로 사용합니다. Substitution·확산·round constant로 key와 state를 갱신하며 Miyaguchi-Preneel 방식으로 cipher 출력·message block·이전 hash를 XOR 결합합니다. Kernel의 wp384/wp256 final은 별도 output 길이 경로입니다.
 * Shash stream·padding·길이 표현·big-endian·vector를 확인합니다. 512bit 내부 hash와 truncation 결과를 구분하며 raw hash를 secret authentication으로 사용하지 않습니다.
 */
static __no_kmsan_checks void wp512_process_buffer(struct wp512_ctx *wctx) {
	int i, r;
	u64 K[8];        /* the round key */
	u64 block[8];    /* mu(buffer) */
	u64 state[8];    /* the cipher state */
	u64 L[8];
	const __be64 *buffer = (const __be64 *)wctx->buffer;

	for (i = 0; i < 8; i++)
		block[i] = be64_to_cpu(buffer[i]);

	state[0] = block[0] ^ (K[0] = wctx->hash[0]);
	state[1] = block[1] ^ (K[1] = wctx->hash[1]);
	state[2] = block[2] ^ (K[2] = wctx->hash[2]);
	state[3] = block[3] ^ (K[3] = wctx->hash[3]);
	state[4] = block[4] ^ (K[4] = wctx->hash[4]);
	state[5] = block[5] ^ (K[5] = wctx->hash[5]);
	state[6] = block[6] ^ (K[6] = wctx->hash[6]);
	state[7] = block[7] ^ (K[7] = wctx->hash[7]);

	for (r = 0; r < WHIRLPOOL_ROUNDS; r++) {

		L[0] = C0[(int)(K[0] >> 56)       ] ^
			   C1[(int)(K[7] >> 48) & 0xff] ^
			   C2[(int)(K[6] >> 40) & 0xff] ^
			   C3[(int)(K[5] >> 32) & 0xff] ^

