 * AEGIS128·변환·상태와 적용 조건
 * AES round 변환을 이용해 여러 block 상태를 갱신하는 AEAD는 AES-GCM과 다른 state·tag 구성을 가집니다.
 * AEGIS128은 여러 128bit state block을 AES round 기반으로 갱신하며 key·nonce·AAD·plaintext를 흡수하고 ciphertext·tag를 만듭니다. Final은 AAD·crypt 길이를 bit 단위로 넣고 일곱 update를 수행해 state XOR tag를 계산합니다. Kernel의 AEGIS128과 다른 AEGIS variant를 구분합니다.
 * Crypto AEAD API의 key·nonce·AAD·tag size·반환 계약을 따릅니다. Key별 nonce 재사용을 피하고 decrypt 인증 실패의 data를 사용하지 않습니다. SIMD 지원과 generic 구현·성능을 구분합니다.
 */
static void crypto_aegis128_final(struct aegis_state *state,
				  union aegis_block *tag_xor,
				  u64 assoclen, u64 cryptlen)
{
	u64 assocbits = assoclen * 8;
	u64 cryptbits = cryptlen * 8;

	union aegis_block tmp;
	unsigned int i;

	tmp.words64[0] = cpu_to_le64(assocbits);
	tmp.words64[1] = cpu_to_le64(cryptbits);

	crypto_aegis_block_xor(&tmp, &state->blocks[3]);

	for (i = 0; i < 7; i++)
		crypto_aegis128_update_a(state, &tmp, false);

	for (i = 0; i < AEGIS128_STATE_BLOCKS; i++)
		crypto_aegis_block_xor(tag_xor, &state->blocks[i]);
}

