/* 학습 해설
 * VMAC·변환·상태와 적용 조건
 * Universal hash의 결과에 nonce별 secret pad를 결합하는 MAC은 hash 단독과 다른 사용 전제를 갖습니다.
 * VMAC는 VHASH 계열의 NH·polynomial·마지막 hash 단계를 거쳐 메시지 값을 얻고 nonce를 block cipher로 암호화해 pad를 만듭니다. v6.12 구현은 64bit tag를 hash+pad modulo 2^64로 출력합니다. Nonce 길이·상위 bit·재사용 조건이 중요하며 encryption이 아니라 인증 기능입니다.
 * Template·key·nonce 입력 규약을 정확히 맞추고 key별 nonce 재사용을 피합니다. Kernel shash 구현은 nonce를 먼저 입력 stream에서 모으는 계약이 있으므로 plain message digest처럼 사용하지 않습니다. Tag 크기·검증 오류를 처리합니다.
 */
static int vmac_final(struct shash_desc *desc, u8 *out)
{
	const struct vmac_tfm_ctx *tctx = crypto_shash_ctx(desc->tfm);
	struct vmac_desc_ctx *dctx = shash_desc_ctx(desc);
	int index;
	u64 hash, pad;

	if (dctx->nonce_size != VMAC_NONCEBYTES)
		return -EINVAL;

	/*
	 * The VMAC specification requires a nonce at least 1 bit shorter than
	 * the block cipher's block length, so we actually only accept a 127-bit
	 * nonce.  We define the unused bit to be the first one and require that
	 * it be 0, so the needed prepending of a 0 bit is implicit.
