/* 학습 해설
 * XCBC·변환·상태와 적용 조건
 * CBC 기반 인증에서 메시지 끝이 완전 block인지에 따라 다른 subkey 처리를 할 수 있습니다.
 * XCBC는 block cipher와 파생 key·constant 값을 사용해 CBC식 인증을 계산합니다. 마지막 block이 full이면 해당 final constant를 사용하고 partial이면 0x80과 zero로 채워 다른 constant를 XOR한 뒤 encrypt합니다. CMAC와 같은 용도 계열이어도 key derivation·final 구성은 다릅니다.
 * 지원 XCBC template의 key·block 크기·stream 계약을 따르고 마지막 block을 final까지 보관하는 이유를 확인합니다. Message 인증과 내용 암호화를 구분하고 tag 검증을 실제 protocol 규약에 맞춥니다.
 */
static int crypto_xcbc_digest_final(struct shash_desc *pdesc, u8 *out)
{
	struct crypto_shash *parent = pdesc->tfm;
	struct xcbc_tfm_ctx *tctx = crypto_shash_ctx(parent);
	struct xcbc_desc_ctx *ctx = shash_desc_ctx(pdesc);
	struct crypto_cipher *tfm = tctx->child;
	int bs = crypto_shash_blocksize(parent);
	u8 *odds = ctx->odds;
	u8 *prev = odds + bs;
	unsigned int offset = 0;

	if (ctx->len != bs) {
		unsigned int rlen;
		u8 *p = odds + ctx->len;

		*p = 0x80;
		p++;

		rlen = bs - ctx->len -1;
		if (rlen)
			memset(p, 0, rlen);

		offset += bs;
	}

	crypto_xor(prev, odds, bs);

