/* 학습 해설
 * NHPoly1305·변환·상태와 적용 조건
 * 큰 입력을 빠른 universal hash로 요약한 뒤 polynomial hash에 넣는 구성은 단계마다 폭과 보안 역할이 다릅니다.
 * NH는 message의 u32와 key를 modulo 2^32로 더하고 서로 떨어진 word 쌍을 곱해 u64 합에 누적합니다. 네 pass의 64bit 결과를 Poly1305 core로 이어 처리합니다. 이 조합은 Adiantum 등의 universal-hash 구성 요소이며 임의 사용의 완성된 one-time MAC으로 자동 보장되지 않습니다.
 * 해당 template·consumer가 정한 key layout·입력 단위·padding·길이 결합을 따릅니다. NHPoly1305를 일반 hash나 raw Poly1305 tag와 혼합하지 않고 block buffering·final 계약을 확인합니다.
 */
static void nh_generic(const u32 *key, const u8 *message, size_t message_len,
		       __le64 hash[NH_NUM_PASSES])
{
	u64 sums[4] = { 0, 0, 0, 0 };

	BUILD_BUG_ON(NH_PAIR_STRIDE != 2);
	BUILD_BUG_ON(NH_NUM_PASSES != 4);

	while (message_len) {
		u32 m0 = get_unaligned_le32(message + 0);
		u32 m1 = get_unaligned_le32(message + 4);
		u32 m2 = get_unaligned_le32(message + 8);
		u32 m3 = get_unaligned_le32(message + 12);

		sums[0] += (u64)(u32)(m0 + key[ 0]) * (u32)(m2 + key[ 2]);
		sums[1] += (u64)(u32)(m0 + key[ 4]) * (u32)(m2 + key[ 6]);
		sums[2] += (u64)(u32)(m0 + key[ 8]) * (u32)(m2 + key[10]);
		sums[3] += (u64)(u32)(m0 + key[12]) * (u32)(m2 + key[14]);
		sums[0] += (u64)(u32)(m1 + key[ 1]) * (u32)(m3 + key[ 3]);
		sums[1] += (u64)(u32)(m1 + key[ 5]) * (u32)(m3 + key[ 7]);
		sums[2] += (u64)(u32)(m1 + key[ 9]) * (u32)(m3 + key[11]);
		sums[3] += (u64)(u32)(m1 + key[13]) * (u32)(m3 + key[15]);
		key += NH_MESSAGE_UNIT / sizeof(key[0]);
		message += NH_MESSAGE_UNIT;
		message_len -= NH_MESSAGE_UNIT;
	}

