/* 학습 해설
 * CTS·변환·상태와 적용 조건
 * 마지막 partial block을 별도 padding으로 길이를 늘리지 않고 암호화하려면 앞 block의 암호문 일부를 재배치할 수 있습니다.
 * Ciphertext stealing은 마지막 full·partial block을 함께 처리해 입력 길이를 보존합니다. Linux CTS template는 child CBC와 마지막 두 block 처리를 연결합니다. 한 block보다 짧은 입력은 거부하고 variant별 최종 순서가 달라 정확한 kernel 형식을 확인해야 합니다.
 * 지원 CTS(CBC) template의 최소 길이·IV·variant·scatterlist·async callback을 맞춥니다. 일반 CBC padding·AEAD와 다른 규약이며 길이 보존만으로 인증이나 nonce 안전성이 생기지 않습니다.
 */
static int crypto_cts_encrypt(struct skcipher_request *req)
{
	struct crypto_skcipher *tfm = crypto_skcipher_reqtfm(req);
	struct crypto_cts_reqctx *rctx = skcipher_request_ctx(req);
	struct crypto_cts_ctx *ctx = crypto_skcipher_ctx(tfm);
	struct skcipher_request *subreq = &rctx->subreq;
	int bsize = crypto_skcipher_blocksize(tfm);
	unsigned int nbytes = req->cryptlen;
	unsigned int offset;

	skcipher_request_set_tfm(subreq, ctx->child);

	if (nbytes < bsize)
		return -EINVAL;

	if (nbytes == bsize) {
		skcipher_request_set_callback(subreq, req->base.flags,
					      req->base.complete,
					      req->base.data);
		skcipher_request_set_crypt(subreq, req->src, req->dst, nbytes,
					   req->iv);
		return crypto_skcipher_encrypt(subreq);
	}

	offset = rounddown(nbytes - 1, bsize);
	rctx->offset = offset;

